    @Override protected void onSaveInstanceState(Bundle saved){rememberBrowse();if(title==null&&scroll!=null)browseY=scroll.getScrollY();if(title!=null&&scroll!=null)detailY=scroll.getScrollY();Bundle positions=new Bundle(),limits=new Bundle();for(Map.Entry<String,Integer> entry:browsePositions.entrySet())positions.putInt(entry.getKey(),entry.getValue());for(Map.Entry<String,Integer> entry:browseLimits.entrySet())limits.putInt(entry.getKey(),entry.getValue());saved.putBundle("browsePositions",positions);saved.putBundle("browseLimits",limits);saved.putInt("detailY",detailY);saved.putInt("browseY",browseY);saved.putInt("browseLimit",browseLimit);saved.putString("query",query);saved.putString("filter",filter);saved.putInt("season",season);if(title!=null){JSONObject seed=new JSONObject();DataStore.put(seed,"id",title.optString("id"));DataStore.put(seed,"noirType",title.optString("noirType"));DataStore.put(seed,"name",title.optString("name"));saved.putString("title",seed.toString());}super.onSaveInstanceState(saved);}
    int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
    TextView text(String value,int size,int color){TextView text=new TextView(this);text.setText(Loc.t(value));text.setTextSize(size);text.setTextColor(color);text.setPadding(0,dp(6),0,dp(8));return text;}
